// Turns a Telegram message into an Agent Office API call, or into a direct reply.
const message = $json.message ?? {};
const chatId = String(message.chat?.id ?? '');
const text = (message.text ?? '').trim();
const allowedChats = String($env.TELEGRAM_ALLOWED_CHAT_IDS ?? '')
  .split(',').map((id) => id.trim()).filter(Boolean);

const HELP = [
  '<b>Agent Office</b>',
  '',
  '/task &lt;description&gt; — create a task',
  '/tasks — your latest tasks',
  '/status &lt;taskId&gt; — task details',
  '/cancel &lt;taskId&gt; — cancel a task',
  '/retry &lt;taskId&gt; — resume a blocked task',
].join('\n');

const reply = (replyText) => ({ json: { chatId, needsApi: false, text: replyText } });
const call = (command, method, path, body = null) => ({
  json: { chatId, needsApi: true, command, method, path, body, correlationId: `telegram-${$json.update_id}` },
});

// Only explicitly allowed chats may spend the local GPU. No list means nobody.
if (!allowedChats.includes(chatId)) {
  return reply(`⛔ This chat is not allowed to use Agent Office.\n\nTo allow it, add <code>${chatId}</code> to TELEGRAM_ALLOWED_CHAT_IDS.`);
}

const match = text.match(/^\/(\w+)(?:@\w+)?(?:\s+([\s\S]*))?$/);
if (!match) {
  return reply(HELP);
}
const command = match[1].toLowerCase();
const argument = (match[2] ?? '').trim();
const TASK_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

switch (command) {
  case 'task': {
    if (!argument) {
      return reply('Usage: /task &lt;description&gt;');
    }
    const firstLine = argument.split('\n')[0];
    const title = firstLine.length > 80 ? `${firstLine.slice(0, 77)}...` : firstLine;
    return call('task', 'POST', '/api/v1/tasks',
      { title, description: argument, source: 'TELEGRAM', externalReference: chatId });
  }
  case 'tasks':
    return call('tasks', 'GET',
      `/api/v1/tasks?source=TELEGRAM&externalReference=${encodeURIComponent(chatId)}&size=10`);
  case 'status':
  case 'cancel':
  case 'retry': {
    if (!TASK_ID.test(argument)) {
      return reply(`Usage: /${command} &lt;taskId&gt;`);
    }
    const paths = {
      status: ['GET', `/api/v1/tasks/${argument}`],
      cancel: ['POST', `/api/v1/tasks/${argument}/cancel`],
      retry: ['POST', `/api/v1/tasks/${argument}/execute`],
    };
    return call(command, ...paths[command]);
  }
  default:
    return reply(HELP);
}

// Turns the Agent Office API response into a Telegram message (HTML parse mode).
const request = $('Parse command').item.json;
const { statusCode, body, error } = $json;
const escape = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const boardLink = (url) => (url ? `\n\nTrello: ${escape(url)}` : '');
const describe = (task) => [
  `ID: <code>${task.id}</code>`,
  `Status: ${task.status}`,
  `Assigned: ${task.assignedAgent ?? 'Manager is routing'}`,
  `Priority: ${task.priority}`,
].join('\n');

function message() {
  if (error || !statusCode) {
    return '⚠️ Agent Office is not reachable right now. Try again in a moment.';
  }
  if (statusCode === 401) {
    return '⚠️ n8n is not authorized to call Agent Office. Check the "Agent Office API key" credential.';
  }
  if (statusCode === 404) {
    return '🔎 Task not found.';
  }
  if (statusCode >= 400) {
    return `⚠️ ${escape(body?.message ?? `Request failed with status ${statusCode}`)}`;
  }
  switch (request.command) {
    case 'task':
      return `✅ <b>Task created</b>\n\n${describe(body)}${boardLink(body.boardUrl)}`;
    case 'status':
      return `📋 <b>${escape(body.title)}</b>\n\n${describe(body)}\nAttempts: ${body.attempt}${boardLink(body.boardUrl)}`;
    case 'cancel':
      return `🚫 Task cancelled\n\n<code>${body.id}</code>`;
    case 'retry':
      return `▶️ Task resumed (${body.status})\n\n<code>${body.id}</code>`;
    case 'tasks':
      if (!body.content?.length) {
        return 'No tasks yet. Create one with /task &lt;description&gt;';
      }
      return ['<b>Your latest tasks</b>', '',
        ...body.content.map((task) => `• ${task.status} — ${escape(task.title)}\n  <code>${task.id}</code>`)].join('\n');
    default:
      return 'Done.';
  }
}

return { json: { chatId: request.chatId, text: message() } };
